// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 hash, uint256 wait) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(actor.code.length == 0);

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // advance well past the guessed block
        vm.roll(block.number + bound(wait, 2, 1000));

        // first settle succeeds
        vm.prank(actor);
        c.settle();

        // invariant: after settle consumed the guess, settle must revert forever
        vm.prank(actor);
        try c.settle() {
            assertTrue(false, "guess not consumed: settle repeatable");
        } catch {
            assertTrue(true);
        }
    }
}
